const heap = {
  root: ['a', 'b'],
  a: ['c'],
  b: ['c'],   // shared, must not be double-marked wrong
  c: [],
  leak: ['leak2'],
  leak2: [],
};
const color = {};
for (const id of Object.keys(heap)) color[id] = 'white';

const grey = ['root'];
color['root'] = 'grey';
while (grey.length) {
  const id = grey.pop();
  for (const ref of heap[id]) {
    if (color[ref] === 'white') { color[ref] = 'grey'; grey.push(ref); }
  }
  color[id] = 'black';
}

const ids = Object.keys(heap);
const live = ids.filter((id) => color[id] === 'black').sort();
const garbage = ids.filter((id) => color[id] === 'white').sort();
console.log('live=' + live.join(',') + ' garbage=' + garbage.join(','));

